 if(!C.can('commerce.'+(merchant?'merchant':'admin')+'.read')){content.innerHTML=C.empty('当前账号暂无访问权限','请由账号管理员授予权益业务权限及数据范围。','<a class="btn" href="../juzhu-commerce.html">返回生活权益</a>');return;}
 definitions=await api(base+'/definitions');
 if(kind==='dashboard'){await dashboard();return;}
 if(kind==='exchanges'){await exchangesView();return;}
 if(kind==='stats'){await statsView();return;}
