  +(rows.length?'<div class="commerce-table-wrap"><table><caption class="sr-only">兑换码列表</caption><thead><tr>'+cols.map(k=>'<th>'+labelsOf[k]+'</th>').join('')+'<th>操作</th></tr></thead><tbody>'+rows.map((r,i)=>'<tr>'+cols.map(k=>'<td>'+cell(r,k)+'</td>').join('')+'<td><div class="row-actions">'+button('详情','detail','data-index="'+i+'"')+((r.state==='unused'||r.state==='expired')&&canWrite()?button('停用','disable-code','data-index="'+i+'"'):'')+'</div></td></tr>').join('')+'</tbody></table></div>':C.empty('暂无兑换码','通过「批量发码」为已发布的演示商品生成兑换码。'))+'<div class="pagination"><span>共 '+total+' 条 · 第 '+page+' 页</span>'+button('上一页','prev',page===1?'disabled':'')+button('下一页','next',page*20>=total?'disabled':'')+'</div></section>';
  document.querySelector('#filter-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);exKind=data.get('kind')||'';state=data.get('state')||'';query=data.get('q')||'';page=1;load();};
