// ── 结算域（结算账单 / 退款执行 / 对账中心 / 商户应结）──
function kpi(l,v,note){return '<div class="commerce-kpi"><span>'+esc(l)+'</span><b>'+esc(String(v))+'</b>'+(note?'<small>'+esc(note)+'</small>':'')+'</div>';}
function batchActions(r){const a=['<div class="row-actions">'];
 if(canFund('read'))a.push(button('详情','batch-detail','data-id="'+r.id+'"'));
 if(canFund('write')&&r.status==='draft')a.push(button('提审','batch-submit','data-id="'+r.id+'"')+button('冻结','batch-freeze','data-id="'+r.id+'"'));
 if(canFund('review')&&r.status==='submitted')a.push(button('复核','batch-review','data-id="'+r.id+'"'));
 if(canFund('write')&&['draft','submitted','approved','executing'].includes(r.status))a.push(button('冻结','batch-freeze','data-id="'+r.id+'"'));
 if(canFund('write')&&r.status==='approved')a.push(button('执行结算','batch-execute','data-id="'+r.id+'"',true));
 if(canFund('write')&&r.status==='frozen')a.push(button('解冻','batch-unfreeze','data-id="'+r.id+'"'));
 if(canFund('write')&&['executing','frozen'].includes(r.status))a.push(button('关账','batch-close','data-id="'+r.id+'"'));
 return a.join('')+'</div>';}
function instructionActions(r){
 const sandbox=canFund('write')?button('沙箱模拟','instr-sandbox','data-request="'+esc(r.request_no)+'"'):'';
 const acts=[];
 if(canFund('write')&&r.status==='submitted')acts.push(button('回执成功','instr-receipt-paid','data-request="'+esc(r.request_no)+'"',true),button('回执失败','instr-receipt-failed','data-request="'+esc(r.request_no)+'"'),sandbox);
 if(canFund('write')&&r.status==='unknown')acts.push(button('查原指令','instr-query','data-id="'+r.id+'"',true),sandbox);
 if(canFund('write')&&r.status==='failed')acts.push(button('重试','instr-retry','data-id="'+r.id+'"',true),button('查原指令','instr-query','data-id="'+r.id+'"'),sandbox);
 return '<div class="row-actions">'+acts.join('')+'</div>';}
